'use strict';

/**
 * 生成 OpenCode V2 CLI plugin。插件在终端内运行，通过 Walker
 * 的 loopback API 收取飞书 prompt，再使用当前 TUI 的本地 SDK 执行。
 */
function getPluginSource(walkerPort, token, heartbeatIntervalMs) {
  const port = Number(walkerPort) || 8787;
  const safeToken = typeof token === 'string' ? token : '';
  const safeHeartbeatMs = Number(heartbeatIntervalMs) > 0 ? Number(heartbeatIntervalMs) : 30000;
  return `// Walker TUI bridge version: 18
// Auto-generated by Walker. Do not edit; Walker may update this file on startup.

const REGISTER_URL = ${JSON.stringify('http://127.0.0.1:' + port + '/opencode/tui-bridge/register')};
const POLL_URL = ${JSON.stringify('http://127.0.0.1:' + port + '/opencode/tui-bridge/poll')};
const EVENTS_URL = ${JSON.stringify('http://127.0.0.1:' + port + '/opencode/tui-bridge/events')};
const DISPOSE_URL = ${JSON.stringify('http://127.0.0.1:' + port + '/opencode/tui-bridge/dispose')};
const WALKER_TOKEN = ${JSON.stringify(safeToken)};
const POLL_INTERVAL_MS = 500;
const HEARTBEAT_INTERVAL_MS = ${safeHeartbeatMs};

function createRuntimeId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') {
    return globalThis.crypto.randomUUID();
  }
  return 'runtime-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
}

async function post(url, body) {
  const headers = { 'Content-Type': 'application/json' };
  if (WALKER_TOKEN) headers.Authorization = 'Bearer ' + WALKER_TOKEN;
  const response = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok || !payload || payload.ok !== true) {
    const message = payload && payload.error && payload.error.message;
    throw new Error(message || 'Walker TUI bridge request failed: HTTP ' + response.status);
  }
  return payload.data || {};
}

function isV2(api) {
  return Boolean(api && api.ui && api.ui.router);
}

function currentSessionId(api) {
  const router = api && api.ui && api.ui.router;
  if (router && typeof router.current === 'function') {
    try {
      const route = router.current() || {};
      const name = route.type || route.name;
      if (name === 'session') return route.sessionID || (route.params && route.params.sessionID) || '';
      return '';
    } catch (_) {}
  }
  const route = api && api.route && api.route.current;
  return route && route.name === 'session' && route.params ? route.params.sessionID : '';
}

function currentDirectory(api) {
  if (api && api.location && api.location.directory) return api.location.directory;
  try {
    const locator = api && api.data && api.data.location && api.data.location.default;
    if (typeof locator === 'function') {
      const location = locator() || {};
      if (location.directory) return location.directory;
    }
  } catch (_) {}
  const directory = api && api.state && api.state.path && api.state.path.directory;
  if (directory) return directory;
  try {
    return typeof process !== 'undefined' && process.cwd ? process.cwd() : '';
  } catch (_) {
    return '';
  }
}

function navigateSession(api, sessionId) {
  const router = api && api.ui && api.ui.router;
  if (router && typeof router.navigate === 'function') {
    return router.navigate({ type: 'session', sessionID: sessionId });
  }
  if (api && api.route && typeof api.route.navigate === 'function') {
    return api.route.navigate('session', { sessionID: sessionId });
  }
}

function eventProperties(event) {
  if (event && event.data && typeof event.data === 'object' && !event.properties) return event.data;
  return event && (event.properties || (event.payload && event.payload.properties)) || {};
}

function sessionStatusType(api, sessionId) {
  const v2 = api && api.data && api.data.session && api.data.session.status;
  const v1 = api && api.state && api.state.session && api.state.session.status;
  const source = typeof v2 === 'function' ? v2 : v1;
  if (typeof source !== 'function') return '';
  let status;
  try {
    status = source(sessionId);
  } catch (_) {
    return '';
  }
  if (!status) return '';
  if (typeof status === 'string') {
    if (status === 'running' || status === 'retry') return 'busy';
    return status;
  }
  return status.type || '';
}

function modelRef(model) {
  if (!model || typeof model !== 'object') return null;
  const id = model.id || model.modelID || model.modelId || '';
  const providerID = model.providerID || model.provider || '';
  if (!id || !providerID) return null;
  const ref = { id: id, providerID: providerID };
  if (model.variant) ref.variant = model.variant;
  return ref;
}

function pickPermissionRequest(properties) {
  return properties && (properties.permission || properties.request || properties.input || properties.data) || properties || {};
}

function errorMessage(value) {
  if (typeof value === 'string' && value) return value;
  if (!value || typeof value !== 'object') return value ? String(value) : 'OpenCode session error';
  if (Array.isArray(value)) {
    for (const item of value) {
      const message = errorMessage(item);
      if (message && message !== 'OpenCode session error' && message !== 'upstream_error') return message;
    }
    return value.length ? errorMessage(value[0]) : 'OpenCode session error';
  }
  if (typeof value.message === 'string' && value.message) return value.message;
  for (const nested of [value.data, value.error, value.cause]) {
    if (nested && nested !== value) {
      const message = errorMessage(nested);
      if (message && message !== 'OpenCode session error') return message;
    }
  }
  if (typeof value.name === 'string' && value.name) return value.name;
  try {
    const serialized = JSON.stringify(value);
    if (serialized && serialized !== '{}') return serialized;
  } catch (_) {}
  return 'OpenCode session error';
}

function stateMessages(api, sessionId) {
  const list = api.data && api.data.session && api.data.session.message && api.data.session.message.list;
  if (typeof list === 'function') return asMessageList(list(sessionId));
  const source = api.state && api.state.session && api.state.session.messages;
  if (typeof source === 'function') return asMessageList(source(sessionId));
  return asMessageList(source && source[sessionId]);
}

function asMessageList(value) {
  return (Array.isArray(value) ? value : []).map(normalizeSessionMessage);
}

function assistantCompleted(message) {
  if (!message || message.role !== 'assistant' || !message.id) return false;
  const info = message.info && typeof message.info === 'object' ? message.info : message;
  const time = (info && info.time) || message.time;
  return Boolean(time && time.completed != null);
}

function messageCompletionTime(message) {
  if (!assistantCompleted(message)) return null;
  const info = message.info && typeof message.info === 'object' ? message.info : message;
  const time = (info && info.time) || message.time;
  const completedAt = Number(time && time.completed);
  return Number.isFinite(completedAt) ? completedAt : null;
}

function visibleFormFields(form) {
  const fields = form && Array.isArray(form.fields) ? form.fields : [];
  return fields.filter((field) => field && field.key && field.hidden !== true && formWhenSatisfied(field, fields));
}

function formWhenSatisfied(field, fields) {
  if (!field || field.when == null) return true;
  const conditions = Array.isArray(field.when) ? field.when : [field.when];
  if (!conditions.length) return true;
  return conditions.every((condition) => formConditionMatches(condition, fields));
}

function formConditionMatches(condition, fields) {
  if (!condition || typeof condition !== 'object') return false;
  const source = fields.find((item) => item && item.key === condition.key);
  const actual = source ? source.default : undefined;
  const op = condition.op || 'eq';
  const expected = condition.value;
  if (op === 'eq') return actual === expected;
  if (op === 'neq' || op === 'ne') return actual !== expected;
  if (op === 'in') return Array.isArray(expected) && expected.indexOf(actual) !== -1;
  if (op === 'notIn' || op === 'nin') return Array.isArray(expected) && expected.indexOf(actual) === -1;
  return false;
}

function formNumericValue(field, raw) {
  if (typeof raw === 'number' && Number.isFinite(raw)) {
    if (field && field.type === 'integer' && !Number.isInteger(raw)) return null;
    return raw;
  }
  if (typeof raw !== 'string') return null;
  const text = raw.trim();
  if (!text || !/^[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][+-]?\\d+)?$/.test(text)) return null;
  const value = Number(text);
  if (!Number.isFinite(value)) return null;
  if (field && field.type === 'integer' && !Number.isInteger(value)) return null;
  return value;
}

function normalizeSessionMessage(message) {
  if (!message || typeof message !== 'object') return message;
  if (message.role === 'assistant' || message.role === 'user') return message;
  if (message.type === 'assistant') {
    const model = message.model || {};
    return {
      id: message.id,
      role: 'assistant',
      content: message.content,
      info: {
        providerID: model.providerID || '',
        modelID: model.id || model.modelID || '',
        tokens: message.tokens,
        time: message.time,
      },
    };
  }
  if (message.type) return Object.assign({ role: message.type }, message);
  return message;
}

function partsForMessage(api, message) {
  if (message && Array.isArray(message.content)) return message.content.map(normalizeContentPart);
  return stateParts(api, message && message.id);
}

function normalizeContentPart(part) {
  if (!part || typeof part !== 'object' || part.type !== 'tool') return part;
  const state = part.state && typeof part.state === 'object' ? part.state : {};
  let output = state.output || part.output || '';
  if (Array.isArray(state.content)) {
    output = state.content.map((item) => item && (item.text || item.uri || '')).filter(Boolean).join('\\n');
  }
  return {
    type: 'tool',
    tool: part.name || part.tool || '',
    name: part.name || part.tool || '',
    state: {
      input: state.input || part.input || {},
      output: output,
      status: state.status || (state.error ? 'error' : ''),
    },
  };
}

function stateParts(api, messageId) {
  const source = api.state && api.state.part;
  if (typeof source === 'function') return source(messageId) || [];
  return source && source[messageId] || [];
}

async function finalEvents(api, sessionId, knownAssistantIds, minCompletedAt) {
  const known = knownAssistantIds instanceof Set ? knownAssistantIds : new Set(knownAssistantIds || []);
  const messages = stateMessages(api, sessionId);
  const assistants = messages.filter((message) => {
    if (!assistantCompleted(message) || known.has(message.id)) return false;
    if (typeof minCompletedAt !== 'number') return true;
    const completedAt = messageCompletionTime(message);
    return completedAt != null && completedAt >= minCompletedAt;
  });
  let assistant = assistants.length ? assistants[assistants.length - 1] : null;
  if (!assistant || !assistant.id) return { messageId: '', events: [] };
  let parts = partsForMessage(api, assistant);
  let info = assistant.info || assistant;
  let finishPart = [...parts].reverse().find((part) => part && part.type === 'step-finish' && part.tokens);
  let tokens = info.tokens || finishPart && finishPart.tokens;
  for (let attempt = 0; !tokens && attempt < 5; attempt++) {
    await new Promise((resolve) => setTimeout(resolve, 20));
    const refreshed = stateMessages(api, sessionId).find((message) => message && message.id === assistant.id);
    if (refreshed) assistant = refreshed;
    parts = partsForMessage(api, assistant);
    info = assistant.info || assistant;
    finishPart = [...parts].reverse().find((part) => part && part.type === 'step-finish' && part.tokens);
    tokens = info.tokens || finishPart && finishPart.tokens;
  }
  const events = [];
  for (const part of parts) {
    const text = part && (part.text || part.content || part.value || '');
    if (part && part.type === 'text' && text) events.push({ type: 'text', data: { text } });
    if (part && part.type === 'reasoning' && text) events.push({ type: 'reasoning', data: { text } });
    if (part && (part.type === 'tool' || part.type === 'tool-use')) {
      events.push({
        type: 'tool_use',
        data: {
          name: part.tool || part.toolName || part.name || '',
          input: part.state && part.state.input || part.input || {},
          output: part.state && part.state.output || part.output || '',
          status: part.state && part.state.status || '',
        },
      });
    }
    if (part && (part.type === 'file' || part.type === 'patch')) {
      events.push({
        type: 'file_edited',
        data: {
          path: part.path || part.file || part.name || '',
          action: part.type === 'patch' ? 'patch' : (part.action || 'edit'),
          linesAdded: part.linesAdded,
          linesRemoved: part.linesRemoved,
        },
      });
    }
  }
  const tokenData = tokens || {};
  const cache = tokenData.cache || {};
  const usage = {
    inputTokens: Number(tokenData.input) || 0,
    outputTokens: Number(tokenData.output) || 0,
    reasoningTokens: Number(tokenData.reasoning) || 0,
    cacheReadTokens: Number(cache.read) || 0,
    cacheWriteTokens: Number(cache.write) || 0,
  };
  const reportedTotal = Number(tokenData.total);
  usage.totalTokens = Number.isFinite(reportedTotal) && reportedTotal >= 0
    ? reportedTotal
    : usage.inputTokens + usage.outputTokens + usage.reasoningTokens + usage.cacheReadTokens + usage.cacheWriteTokens;
  const done = { reason: 'idle' };
  if (info.providerID || info.modelID) {
    done.model = { providerID: info.providerID || '', modelID: info.modelID || '' };
  }
  if (tokens) done.usage = usage;
  events.push({ type: 'done', data: done });
  return { messageId: assistant.id, events };
}

function extractSessionId(result) {
  if (!result || typeof result !== 'object') return '';
  if (result.data && result.data.data && typeof result.data.data.id === 'string' && result.data.data.id) return result.data.data.id;
  if (result.data && typeof result.data.id === 'string' && result.data.id) return result.data.id;
  if (typeof result.id === 'string' && result.id) return result.id;
  if (typeof result.sessionID === 'string' && result.sessionID) return result.sessionID;
  if (typeof result.sessionId === 'string' && result.sessionId) return result.sessionId;
  return '';
}

function describeCreateResult(result) {
  if (!result || typeof result !== 'object') return String(result || '');
  const keys = Object.keys(result).slice(0, 8).join(',');
  const data = result.data && typeof result.data === 'object' ? Object.keys(result.data).slice(0, 8).join(',') : '';
  return 'keys=' + keys + (data ? ' dataKeys=' + data : '');
}

function extractSessionObject(result) {
  if (!result || typeof result !== 'object') return null;
  if (result.data && result.data.data && typeof result.data.data === 'object') return result.data.data;
  if (result.data && typeof result.data === 'object') return result.data;
  return result;
}

function extractWorkspaceId(result) {
  const session = extractSessionObject(result);
  if (!session || typeof session !== 'object') return '';
  if (typeof session.workspaceID === 'string' && session.workspaceID) return session.workspaceID;
  if (typeof session.workspaceId === 'string' && session.workspaceId) return session.workspaceId;
  if (session.location && typeof session.location.workspaceID === 'string') return session.location.workspaceID;
  return '';
}

function isShapeCompatibilityError(value) {
  const message = errorMessage(value).toLowerCase();
  if (!message.includes('body')) return false;
  return message.includes('unknown option')
    || message.includes('unexpected option')
    || message.includes('not allowed')
    || message.includes('unrecognized key')
    || message.includes('unknown key')
    || message.includes('unexpected key');
}

async function setup(api) {
  const runtimeId = createRuntimeId();
  const activeDeliveries = new Map();
  let activeQuestionDelivery = null;
  const sentAssistantIds = new Set();
  const completedPromptSessions = new Set();
  let stopped = false;
  let busy = false;
  let activeSessionId = currentSessionId(api);
  let lastRegisteredSessionId = '';
  let lastRegisteredAt = 0;

  let activeClear = null;
  const clearEventBuffer = [];
  let pendingClearCreatedSessionId = '';
  const knownForms = new Map();
  const repliedFormIds = new Set();

  function bridgeLog(deliveryId, type, stage) {
    console.warn('[walker-bridge]', {
      deliveryId: deliveryId || '',
      type: type || '',
      stage: stage || '',
    });
  }

  async function register(sessionId, force, extra) {
    if (!force && sessionId === lastRegisteredSessionId && lastRegisteredAt) return;
    const body = {
      runtimeId,
      sessionId,
      cwd: currentDirectory(api),
      opencodeVersion: api.app && api.app.version || '',
      bridgeProtocolVersion: 5,
    };
    if (extra) Object.assign(body, extra);
    await post(REGISTER_URL, body);
    if (!extra || !extra.controlDeliveryId) {
      lastRegisteredSessionId = sessionId;
      lastRegisteredAt = Date.now();
    }
  }

  async function report(sessionId, deliveryId, events, error, control, deliveryState, assistantMessageId) {
    const body = { runtimeId, sessionId, deliveryId: deliveryId || undefined, events: events || [], error };
    if (control) body.control = control;
    if (deliveryState) body.deliveryState = deliveryState;
    if (assistantMessageId) body.assistantMessageId = assistantMessageId;
    return post(EVENTS_URL, body);
  }

  function startHeartbeat(sessionId, deliveryId) {
    const entry = activeDeliveries.get(sessionId);
    if (!entry || entry.heartbeatTimer) return;
    entry.heartbeatTimer = setInterval(async () => {
      try {
        await report(sessionId, deliveryId, [], null, null, 'heartbeat');
      } catch (_) {}
    }, HEARTBEAT_INTERVAL_MS);
    if (entry.heartbeatTimer.unref) entry.heartbeatTimer.unref();
  }

  function stopHeartbeat(sessionId) {
    const entry = activeDeliveries.get(sessionId);
    if (!entry || !entry.heartbeatTimer) return;
    clearInterval(entry.heartbeatTimer);
    entry.heartbeatTimer = null;
  }

  function questionReplyError(error, code, deliveryPhase, sdkInvoked, safeToRetry) {
    return {
      message: errorMessage(error) || 'question reply failed',
      code: code || error && error.code || 'QUESTION_REPLY_FAILED',
      deliveryPhase,
      sdkInvoked: Boolean(sdkInvoked),
      safeToRetry: Boolean(safeToRetry),
    };
  }

  function errorMessage(error) {
    if (!error) return '';
    if (typeof error === 'string') return error;
    if (typeof error.message === 'string') return error.message;
    if (error.message) return stringifyErrorValue(error.message);
    if (typeof error.error === 'string') return error.error;
    if (error.error) return stringifyErrorValue(error.error);
    if (error.body) return stringifyErrorValue(error.body);
    if (error.data) return stringifyErrorValue(error.data);
    return stringifyErrorValue(error);
  }

  function stringifyErrorValue(value) {
    try {
      return JSON.stringify(value);
    } catch (_) {
      return String(value);
    }
  }

  function validQuestionReply(delivery) {
    return typeof delivery.requestID === 'string' && delivery.requestID
      && Array.isArray(delivery.answers) && delivery.answers.length > 0
      && delivery.answers.every((answer) => Array.isArray(answer) && answer.length > 0
        && answer.every((value) => typeof value === 'string' && value));
  }

  function validPermissionReply(delivery) {
    return typeof delivery.permissionId === 'string' && delivery.permissionId
      && typeof delivery.response === 'string' && delivery.response;
  }

  function permissionResponseForSdk(response, remember) {
    if (response === 'deny' || response === 'reject') return 'reject';
    if (response === 'always') return 'always';
    if (remember) return 'always';
    return 'once';
  }

  function startQuestionHeartbeat() {
    const control = activeQuestionDelivery;
    if (!control || control.heartbeatTimer) return;
    control.heartbeatTimer = setInterval(async () => {
      try {
        await report(control.sessionId, control.deliveryId, [], null, null, 'heartbeat');
      } catch (_) {}
    }, HEARTBEAT_INTERVAL_MS);
    if (control.heartbeatTimer.unref) control.heartbeatTimer.unref();
  }

  function clearQuestionDelivery() {
    if (!activeQuestionDelivery) return;
    if (activeQuestionDelivery.heartbeatTimer) clearInterval(activeQuestionDelivery.heartbeatTimer);
    activeQuestionDelivery = null;
  }

  function rememberForm(form) {
    if (!form || !form.id) return;
    knownForms.set(form.id, form);
  }

  function optionValue(field, label) {
    const options = field && field.options || [];
    const match = options.find((option) => option && (option.label === label || option.value === label));
    return match ? match.value : label;
  }

  function formAnswerFromWalker(requestID, answers) {
    const form = knownForms.get(requestID);
    if (!form) {
      return { ok: false, error: questionReplyError(new Error('form is not known'), 'FORM_REPLY_UNKNOWN', 'queued', false, true) };
    }
    if (repliedFormIds.has(requestID)) {
      return { ok: false, error: questionReplyError(new Error('form already replied'), 'FORM_ALREADY_REPLIED', 'queued', false, false) };
    }
    const fields = visibleFormFields(form);
    const provided = Array.isArray(answers) ? answers : [];
    if (!fields.length || provided.length !== fields.length) {
      return { ok: false, error: questionReplyError(new Error('form reply does not cover visible fields'), 'FORM_REPLY_INVALID', 'queued', false, true) };
    }
    const record = {};
    const invalid = [];
    fields.forEach((field, index) => {
      const selected = provided[index] || [];
      if (!selected.length) {
        invalid.push(field.key);
        return;
      }
      if (field.type === 'multiselect') {
        record[field.key] = selected.map((label) => optionValue(field, label));
        return;
      }
      if (field.type === 'boolean') {
        const value = selected[0];
        record[field.key] = value === 'true' || value === '是' || value === true;
        return;
      }
      if (field.type === 'number' || field.type === 'integer') {
        const value = formNumericValue(field, selected[0]);
        if (value == null) {
          invalid.push(field.key);
          return;
        }
        record[field.key] = value;
        return;
      }
      const value = selected[0];
      record[field.key] = field.options ? optionValue(field, value) : value;
    });
    if (invalid.length) {
      return { ok: false, error: questionReplyError(new Error('form reply has invalid visible fields: ' + invalid.join(',')), 'FORM_REPLY_INVALID', 'queued', false, true) };
    }
    return { ok: true, answer: record };
  }

  function questionsFromForm(form) {
    return visibleFormFields(form).map((field) => {
      const question = {
        question: field.description || field.title || field.key,
        header: field.title || (form && form.title) || '确认',
      };
      if (Array.isArray(field.options) && field.options.length) {
        question.options = field.options.map((option) => ({
          label: option.label || option.value,
          description: option.description || '',
        }));
      }
      if (field.type === 'multiselect') question.multiple = true;
      return question;
    });
  }

  function answersFromForm(formId, answer) {
    if (!answer || typeof answer !== 'object' || Array.isArray(answer)) return [];
    const form = knownForms.get(formId);
    const fields = visibleFormFields(form);
    const keys = fields.length ? fields.map((field) => field.key) : Object.keys(answer).sort();
    return keys.map((key) => {
      const value = answer[key];
      if (Array.isArray(value)) return value.map((item) => String(item));
      if (value == null) return [];
      return [String(value)];
    }).filter((item) => item.length > 0);
  }

  async function submitPrompt(api, sessionId, delivery) {
    const sessionClient = api.client && api.client.session;
    if (!sessionClient) throw new Error('OpenCode session client is unavailable');
    if (isV2(api) && typeof sessionClient.prompt === 'function') {
      if (delivery.model && typeof sessionClient.switchModel === 'function') {
        const model = modelRef(delivery.model);
        if (model) await sessionClient.switchModel({ sessionID: sessionId, model: model });
      }
      return sessionClient.prompt({ sessionID: sessionId, text: delivery.text || '' });
    }
    const promptParams = {
      sessionID: sessionId,
      parts: [{ type: 'text', text: delivery.text || '' }],
    };
    if (delivery.model) promptParams.model = delivery.model;
    return api.client.session.promptAsync(promptParams);
  }

  async function progressQuestionDelivery() {
    const control = activeQuestionDelivery;
    if (!control) return;
    if (control.state === 'awaitingAccepted') {
      try {
        const accepted = await report(control.sessionId, control.deliveryId, [], null, null, 'accepted');
        if (accepted && accepted.expired === true) {
          clearQuestionDelivery();
          return;
        }
      } catch (_) {
        return;
      }
      control.state = 'executingSdk';
      const formClient = api.client && api.client.session && api.client.session.form;
      const questionClient = api.client && api.client.question;
      const useForm = isV2(api) && formClient && typeof formClient.reply === 'function';
      const useQuestion = !useForm && questionClient && typeof questionClient.reply === 'function';
      if (!useForm && !useQuestion) {
        control.finalError = questionReplyError(
          new Error('OpenCode SDK question.reply is unavailable'),
          'QUESTION_REPLY_UNSUPPORTED', 'queued', false, false,
        );
        control.state = 'finalizing';
        return progressQuestionDelivery();
      }
      if (useForm) {
        const mapped = formAnswerFromWalker(control.requestID, control.answers);
        if (!mapped.ok) {
          control.finalError = mapped.error;
          control.sdkInvoked = false;
          control.state = 'finalizing';
          return progressQuestionDelivery();
        }
        control.preparedAnswer = mapped.answer;
      }
      control.sdkInvoked = true;
      startQuestionHeartbeat();
      try {
        const result = useForm
          ? await formClient.reply({ sessionID: control.sessionId, formID: control.requestID, answer: control.preparedAnswer })
          : await questionClient.reply({ requestID: control.requestID, answers: control.answers });
        if (result && result.error) throw result.error;
        if (useForm) repliedFormIds.add(control.requestID);
        control.finalError = null;
      } catch (error) {
        control.finalError = questionReplyError(error, error && error.code || 'QUESTION_REPLY_SDK_FAILED', 'leased', true, false);
      }
      control.state = 'finalizing';
    }
    if (control.state === 'finalizing') {
      const stage = control.finalError ? 'reply' : 'final';
      try {
        await report(control.sessionId, control.deliveryId, [], control.finalError, null, 'final');
        clearQuestionDelivery();
        bridgeLog(control.deliveryId, 'question_reply', stage);
      } catch (_) {
        bridgeLog(control.deliveryId, 'question_reply', 'report');
      }
    }
  }

  async function executeQuestionDelivery(delivery) {
    if (activeQuestionDelivery) return;
    const control = {
      deliveryId: delivery.deliveryId,
      sessionId: delivery.sessionId,
      requestID: delivery.requestID,
      answers: delivery.answers,
      heartbeatTimer: null,
      state: 'awaitingAccepted',
      sdkInvoked: false,
      finalError: null,
    };
    activeQuestionDelivery = control;
    if (!validQuestionReply(delivery)) {
      control.state = 'finalizing';
      control.finalError = questionReplyError(
        new Error('question_reply requires a requestID and non-empty string answers'),
        'QUESTION_REPLY_INVALID_PAYLOAD', 'queued', false, false,
      );
    }
    await progressQuestionDelivery();
  }

  async function executePermissionDelivery(delivery) {
    const sessionId = delivery.sessionId;
    try {
      const accepted = await report(sessionId, delivery.deliveryId, [], null, null, 'accepted');
      if (accepted && accepted.expired === true) return;
    } catch (_) {
      return;
    }

    let sdkInvoked = false;
    let finalError = null;
    const entry = { heartbeatTimer: null };
    activeDeliveries.set(sessionId, entry);
    try {
      if (!validPermissionReply(delivery)) {
        finalError = questionReplyError(
          new Error('permission_reply requires a permissionId and response'),
          'PERMISSION_REPLY_INVALID_PAYLOAD', 'queued', false, false,
        );
      } else {
        const permissionClient = api.client && api.client.permission;
        const sdkResponse = permissionResponseForSdk(delivery.response, delivery.remember);
        if (permissionClient && typeof permissionClient.reply === 'function') {
          sdkInvoked = true;
          startHeartbeat(sessionId, delivery.deliveryId);
          const replyInput = isV2(api)
            ? { sessionID: sessionId, requestID: delivery.permissionId, decision: sdkResponse }
            : { requestID: delivery.permissionId, reply: sdkResponse, directory: currentDirectory(api) };
          const result = await permissionClient.reply(replyInput);
          if (result && result.error) throw result.error;
        } else {
          finalError = questionReplyError(
            new Error('OpenCode SDK permission reply is unavailable'),
            'PERMISSION_REPLY_UNSUPPORTED', 'queued', false, false,
          );
        }
      }
    } catch (error) {
      finalError = questionReplyError(error, error && error.code || 'PERMISSION_REPLY_SDK_FAILED', sdkInvoked ? 'leased' : 'queued', sdkInvoked, false);
    } finally {
      stopHeartbeat(sessionId);
      activeDeliveries.delete(sessionId);
    }

    await report(sessionId, delivery.deliveryId, [], finalError, null, 'final').catch(() => {});
  }

  async function executeDelivery(delivery) {
    const deliveryType = delivery && delivery.type || 'prompt';
    if (!delivery || !delivery.deliveryId) {
      bridgeLog('', deliveryType, 'rejected');
      return;
    }
    bridgeLog(delivery.deliveryId, deliveryType, 'received');
    if (delivery.type === 'question_reply') {
      await executeQuestionDelivery(delivery);
      return;
    }
    if (delivery.type === 'permission_reply') {
      await executePermissionDelivery(delivery);
      return;
    }
    if (delivery.type === 'clear') {
      await executeClearDelivery(delivery);
      return;
    }
    const sessionId = activeSessionId;
    if (sessionId !== delivery.sessionId) {
      bridgeLog(delivery.deliveryId, deliveryType, 'session-mismatch');
      return;
    }
    const startedAt = Date.now();
    let knownAssistantIds = new Set();
    let baselineReady = true;
    try {
      knownAssistantIds = new Set();
      for (const message of stateMessages(api, sessionId)) {
        if (message && message.role === 'assistant' && message.id) knownAssistantIds.add(message.id);
      }
    } catch (_) {
      baselineReady = false;
      knownAssistantIds = new Set();
    }
    activeDeliveries.set(sessionId, {
      deliveryId: delivery.deliveryId,
      type: deliveryType,
      heartbeatTimer: null,
      knownAssistantIds,
      baselineReady,
      startedAt,
      reporting: false,
    });
    try {
      await report(sessionId, delivery.deliveryId, [], null, null, 'accepted');
      if (currentSessionId(api) !== sessionId) {
        navigateSession(api, sessionId);
      }
      const result = await submitPrompt(api, sessionId, delivery);
      if (result && result.error) throw new Error(errorMessage(result.error));
      startHeartbeat(sessionId, delivery.deliveryId);
      bridgeLog(delivery.deliveryId, deliveryType, 'accepted');
    } catch (error) {
      stopHeartbeat(sessionId);
      activeDeliveries.delete(sessionId);
      completedPromptSessions.add(sessionId);
      bridgeLog(delivery.deliveryId, deliveryType, 'prompt');
      await report(sessionId, delivery.deliveryId, [], { message: error.message || String(error) }, null, 'final').catch(() => {});
    }
  }

  async function executeClearDelivery(delivery) {
    const oldSessionId = delivery.sessionId;
    if (activeSessionId !== oldSessionId) return;

    activeClear = {
      deliveryId: delivery.deliveryId,
      oldSessionId,
      suppressSessionId: null,
      navigated: false,
      completed: false,
      failed: false,
    };

    let newSessionId = '';
    try {
      pendingClearCreatedSessionId = '';
      const createResult = await createClearSession(delivery.title, oldSessionId);
      newSessionId = extractSessionId(createResult);
      if (!newSessionId) newSessionId = await waitForCreatedSessionId();
      if (!newSessionId) throw new Error('OpenCode session create returned no session id (' + describeCreateResult(createResult) + ')');
      if (!activeClear || activeClear.deliveryId !== delivery.deliveryId) return;
      activeClear.suppressSessionId = newSessionId;
    } catch (error) {
      if (activeClear && activeClear.deliveryId === delivery.deliveryId) {
        activeClear.failed = true;
        await report(oldSessionId, delivery.deliveryId, [], { message: error.message || String(error) }).catch(() => {});
        activeClear = null;
        pendingClearCreatedSessionId = '';
        flushClearEventBuffer();
      }
      return;
    }

    try {
      navigateSession(api, newSessionId);
      activeClear.navigated = true;
    } catch (error) {
      if (activeClear && activeClear.deliveryId === delivery.deliveryId) {
        activeClear.failed = true;
        await report(oldSessionId, delivery.deliveryId, [], { message: error.message || String(error) }).catch(() => {});
        activeClear = null;
        pendingClearCreatedSessionId = '';
        flushClearEventBuffer();
      }
      return;
    }

    const controlBody = { runtimeId, sessionId: oldSessionId, deliveryId: delivery.deliveryId, control: { type: 'clear', newSessionId } };
    const registerBody = {
      runtimeId,
      sessionId: newSessionId,
      cwd: currentDirectory(api),
      opencodeVersion: api.app && api.app.version || '',
      bridgeProtocolVersion: 5,
      controlDeliveryId: delivery.deliveryId,
    };

    let controlOk = false;
    let registerOk = false;
    let controlError = null;
    let registerError = null;

    try {
      await post(EVENTS_URL, controlBody);
      controlOk = true;
    } catch (error) {
      controlError = error;
    }

    try {
      await post(REGISTER_URL, registerBody);
      registerOk = true;
    } catch (error) {
      registerError = error;
    }

    if (controlOk && registerOk) {
      activeClear.completed = true;
      activeSessionId = newSessionId;
      lastRegisteredSessionId = newSessionId;
      lastRegisteredAt = Date.now();
      activeClear = null;
      pendingClearCreatedSessionId = '';
      flushClearEventBuffer();
      return;
    }

    const failError = controlError || registerError;
    const failMessage = failError ? (failError.message || String(failError)) : 'clear associated reporting failed';
    if (activeClear && activeClear.deliveryId === delivery.deliveryId) {
      activeClear.failed = true;
      await report(oldSessionId, delivery.deliveryId, [], { message: failMessage }).catch(() => {});
      if (activeClear.navigated) {
        try {
          navigateSession(api, oldSessionId);
        } catch (rollbackError) {
          await report(oldSessionId, delivery.deliveryId, [], {
            message: failMessage + '；回滚失败：' + (rollbackError.message || String(rollbackError)) + '，请手工切回旧 session',
          }).catch(() => {});
        }
      }
      activeClear = null;
      pendingClearCreatedSessionId = '';
      flushClearEventBuffer();
    }
  }

  function currentWorkspaceId() {
    if (api.location && api.location.workspaceID) return api.location.workspaceID;
    try {
      const locator = api.data && api.data.location && api.data.location.default;
      if (typeof locator === 'function') {
        const location = locator() || {};
        if (location.workspaceID) return location.workspaceID;
      }
    } catch (_) {}
    try {
      if (api.workspace && typeof api.workspace.current === 'function') {
        return api.workspace.current() || '';
      }
    } catch (_) {}
    return '';
  }

  function sessionQuery(workspaceID) {
    const query = {};
    const directory = currentDirectory(api);
    if (directory) query.directory = directory;
    if (workspaceID) query.workspace = workspaceID;
    return Object.keys(query).length ? query : undefined;
  }

  async function currentSessionWorkspaceId(sessionId) {
    const activeWorkspaceID = currentWorkspaceId();
    if (activeWorkspaceID) return activeWorkspaceID;
    const sessionClient = api.client && api.client.session;
    if (!sessionClient || typeof sessionClient.get !== 'function' || !sessionId) return '';
    try {
      const input = isV2(api) ? { sessionID: sessionId } : { path: { id: sessionId } };
      if (!isV2(api)) {
        const query = sessionQuery();
        if (query) input.query = query;
      }
      const result = await sessionClient.get(input);
      if (result && result.error) return '';
      return extractWorkspaceId(result);
    } catch (_) {
      return '';
    }
  }

  async function createClearSession(title, oldSessionId) {
    if (isV2(api)) {
      const input = {};
      if (typeof title === 'string' && title) input.title = title;
      const directory = currentDirectory(api);
      if (directory) input.location = { directory: directory };
      try {
        const result = await api.client.session.create(input);
        if (result && result.error) throw result.error;
        return result;
      } catch (error) {
        throw new Error('OpenCode session create failed: ' + (errorMessage(error) || describeCreateResult(error)));
      }
    }
    const body = {};
    if (typeof title === 'string' && title) body.title = title;
    const workspaceID = await currentSessionWorkspaceId(oldSessionId);
    if (workspaceID) body.workspaceID = workspaceID;
    const modernInput = { body };
    const query = sessionQuery(workspaceID);
    if (query) modernInput.query = query;
    if (workspaceID) modernInput.headers = { 'x-opencode-workspace': workspaceID };
    try {
      const result = await api.client.session.create(modernInput);
      if (!result || !result.error) return result;
      if (!isShapeCompatibilityError(result.error)) throw result.error;
      const legacyResult = await api.client.session.create({ title });
      if (legacyResult && legacyResult.error) throw legacyResult.error;
      return legacyResult;
    } catch (error) {
      throw new Error('OpenCode session create failed: ' + (errorMessage(error) || describeCreateResult(error)));
    }
  }

  async function waitForCreatedSessionId() {
    for (let i = 0; i < 10; i++) {
      if (pendingClearCreatedSessionId) return pendingClearCreatedSessionId;
      await new Promise((resolve) => setTimeout(resolve, 20));
    }
    return pendingClearCreatedSessionId;
  }

  function flushClearEventBuffer() {
    if (activeClear) return;
    const buffered = clearEventBuffer.splice(0);
    for (const item of buffered) {
      if (item.type === 'session.created') {
        handleSessionCreated(item.event, true);
      } else if (item.type === 'tui.session.select') {
        handleTuiSessionSelect(item.event, true);
      }
    }
  }

  async function tick() {
    if (stopped || busy) return;
    const routedSessionId = currentSessionId(api);
    if (!activeSessionId) activeSessionId = routedSessionId;
    else if (isV2(api) && routedSessionId && routedSessionId !== activeSessionId) {
      const clearing = activeClear && (activeClear.suppressSessionId === routedSessionId || activeClear.oldSessionId === routedSessionId);
      if (!clearing) {
        activeSessionId = routedSessionId;
        lastRegisteredSessionId = '';
        lastRegisteredAt = 0;
      }
    }
    const sessionId = activeSessionId;
    if (!sessionId) return;
    if (activeClear && activeClear.oldSessionId === sessionId) return;
    if (activeQuestionDelivery) {
      busy = true;
      try {
        await progressQuestionDelivery();
      } finally {
        busy = false;
      }
      return;
    }
    const statusType = sessionStatusType(api, sessionId);
    busy = true;
    try {
      await register(sessionId, false);
      const parentActive = activeDeliveries.has(sessionId);
      const acceptedTypes = parentActive || (statusType && statusType !== 'idle')
        ? ['question_reply', 'permission_reply']
        : ['prompt', 'clear', 'question_reply', 'permission_reply'];
      const data = await post(POLL_URL, { runtimeId, sessionId, acceptedTypes });
      if (data.delivery) await executeDelivery(data.delivery);
    } catch (_) {
      lastRegisteredAt = 0;
    } finally {
      busy = false;
    }
  }

  async function selectSession(sessionId) {
    if (!sessionId) return;
    if (activeClear && activeClear.suppressSessionId === sessionId) return;
    if (sessionId !== activeSessionId) {
      activeSessionId = sessionId;
      lastRegisteredSessionId = '';
      lastRegisteredAt = 0;
    }
    await tick();
  }

  function handleSessionCreated(event, fromBuffer) {
    const properties = eventProperties(event);
    const info = properties.info || {};
    if (info.parentID || info.parentId || properties.parentID || properties.parentId) return;
    const sessionId = properties.sessionID || properties.sessionId || info.id;
    if (!sessionId) return;
    if (activeClear) {
      if (!activeClear.suppressSessionId && sessionId !== activeClear.oldSessionId) pendingClearCreatedSessionId = sessionId;
      if (activeClear.suppressSessionId === sessionId) return;
      if (!fromBuffer) clearEventBuffer.push({ type: 'session.created', event });
      return;
    }
    return selectSession(sessionId);
  }

  function handleTuiSessionSelect(event, fromBuffer) {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId;
    if (!sessionId) return;
    if (activeClear) {
      if (activeClear.suppressSessionId === sessionId) return;
      if (!fromBuffer) clearEventBuffer.push({ type: 'tui.session.select', event });
      return;
    }
    return selectSession(sessionId);
  }

  const eventStops = [];
  function onPluginEvent(type, handler) {
    if (api.data && typeof api.data.on === 'function') {
      try {
        const stop = api.data.on(type, handler);
        if (typeof stop === 'function') eventStops.push(stop);
      } catch (_) {}
    }
    if (api.event && typeof api.event.on === 'function') {
      try {
        const stop = api.event.on(type, handler);
        if (typeof stop === 'function') eventStops.push(stop);
      } catch (_) {}
    }
  }

  onPluginEvent('session.created', async (event) => {
    await handleSessionCreated(event);
  });

  onPluginEvent('tui.session.select', async (event) => {
    await handleTuiSessionSelect(event);
  });

  async function handleSessionIdle(event) {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId;
    if (!sessionId) return;
    const entry = activeDeliveries.get(sessionId);
    if (!entry || !entry.deliveryId || entry.reporting) return;
    const deliveryType = entry.type || 'prompt';
    let result;
    try {
      const minCompletedAt = entry.baselineReady === false ? entry.startedAt : undefined;
      result = await finalEvents(api, sessionId, entry.knownAssistantIds, minCompletedAt);
    } catch (_) {
      bridgeLog(entry.deliveryId, deliveryType, 'cache-sync');
      return;
    }
    if (!result.messageId || sentAssistantIds.has(result.messageId)) {
      if (result.messageId) entry.knownAssistantIds.add(result.messageId);
      bridgeLog(entry.deliveryId, deliveryType, 'awaiting-reply');
      return;
    }
    entry.reporting = true;
    try {
      await report(sessionId, entry.deliveryId, result.events, null, null, 'final', result.messageId);
      sentAssistantIds.add(result.messageId);
      stopHeartbeat(sessionId);
      activeDeliveries.delete(sessionId);
      completedPromptSessions.add(sessionId);
      bridgeLog(entry.deliveryId, deliveryType, 'final');
    } catch (_) {
      entry.reporting = false;
      bridgeLog(entry.deliveryId, deliveryType, 'report');
    }
  }
  onPluginEvent('session.idle', handleSessionIdle);
  onPluginEvent('session.execution.succeeded', handleSessionIdle);

  function markManualTurn(event) {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId;
    if (sessionId && !activeDeliveries.has(sessionId)) completedPromptSessions.delete(sessionId);
  }
  onPluginEvent('session.busy', markManualTurn);
  onPluginEvent('session.status', (event) => {
    if (eventProperties(event).status && eventProperties(event).status.type === 'busy') markManualTurn(event);
  });

  async function handleSessionError(event) {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    const entry = activeDeliveries.get(sessionId);
    if (!entry) {
      if (sessionId === activeSessionId && !completedPromptSessions.has(sessionId)) {
        completedPromptSessions.add(sessionId);
        try {
          await report(sessionId, '', [], { message: errorMessage(properties.error) }, null, null);
        } catch (_) {
          completedPromptSessions.delete(sessionId);
        }
      }
      return;
    }
    const deliveryId = entry.deliveryId;
    const deliveryState = 'final';
    stopHeartbeat(sessionId);
    activeDeliveries.delete(sessionId);
    if (deliveryId) completedPromptSessions.add(sessionId);
    const error = { message: errorMessage(properties.error) };
    await report(sessionId, deliveryId, [], error, null, deliveryState).catch(() => {});
  }
  onPluginEvent('session.error', handleSessionError);
  onPluginEvent('session.execution.failed', handleSessionError);

  function reportPermissionEvent(type, event) {
    const properties = eventProperties(event);
    const request = pickPermissionRequest(properties);
    const metadata = request.metadata || properties.metadata || {};
    const sessionId = properties.sessionID || properties.sessionId || request.sessionID || request.sessionId || activeSessionId;
    if (!sessionId) return Promise.resolve();
    if (type === 'permission_replied') {
      const permissionId = properties.permissionId || properties.requestID || properties.id || request.permissionId || request.requestID || request.id || '';
      if (!permissionId) return Promise.resolve();
      return report(sessionId, '', [{ type, data: {
        permissionId,
        response: properties.response || properties.reply || properties.action || properties.decision || request.response || request.reply || request.action || request.decision || '',
        sessionID: sessionId,
      } }], null, null, null).catch(() => {});
    }
    const permissionId = properties.id || properties.permissionId || request.id || request.permissionId || '';
    if (!permissionId) return Promise.resolve();
    const permissionType = properties.permission || request.permission || properties.action || request.action || properties.type || request.type || '';
    const permissionPatterns = Array.isArray(properties.patterns) ? properties.patterns
      : (Array.isArray(request.patterns) ? request.patterns
        : (Array.isArray(properties.resources) ? properties.resources
          : (Array.isArray(request.resources) ? request.resources
            : (Array.isArray(metadata.patterns) ? metadata.patterns : []))));
    const title = properties.title || request.title || permissionTitle(permissionType, permissionPatterns);
    return report(sessionId, '', [{ type: 'permission', data: {
      id: permissionId,
      type: permissionType,
      title: title,
      description: properties.description || request.description || '',
      metadata: {
        ...metadata,
        patterns: permissionPatterns.length ? permissionPatterns : undefined,
        pattern: metadata.pattern || request.pattern || properties.pattern || undefined,
      },
      sessionID: sessionId,
      messageID: properties.messageID || properties.messageId || request.messageID || request.messageId || (properties.source && properties.source.messageID) || (request.source && request.source.messageID) || '',
      callID: properties.callID || properties.callId || request.callID || request.callId || (properties.source && properties.source.id) || (request.source && request.source.id) || undefined,
    } }], null, null, null).catch(() => {});
  }

  function permissionTitle(permissionType, patterns) {
    if (!permissionType || typeof permissionType !== 'string') return '';
    const map = {
      external_directory: '访问外部目录',
      bash: '执行 bash 命令',
      edit: '编辑文件',
      write: '写入文件',
      webfetch: '访问网络',
    };
    const base = map[permissionType] || ('权限请求: ' + permissionType);
    const path = extractPermissionPath(patterns);
    return path ? (base + ' ' + path) : base;
  }

  function extractPermissionPath(patterns) {
    if (!Array.isArray(patterns) || patterns.length === 0) return '';
    const first = patterns[0];
    if (typeof first !== 'string' || !first) return '';
    return first.replace(/[/\\\\]*\\*+$/, '').replace(/[\\*]/g, '');
  }

  onPluginEvent('permission.asked', async (event) => {
    await reportPermissionEvent('permission', event);
  });

  onPluginEvent('permission.updated', async (event) => {
    await reportPermissionEvent('permission', event);
  });

  onPluginEvent('permission.replied', async (event) => {
    await reportPermissionEvent('permission_replied', event);
  });

  function reportQuestionEvent(type, event) {
    const properties = eventProperties(event);
    const request = properties.request || properties;
    const sessionID = properties.sessionID || properties.sessionId || request.sessionID || request.sessionId || activeSessionId;
    const requestID = request.requestID || request.id || properties.requestID || properties.id;
    if (!sessionID || !requestID) {
      console.error('Walker received an invalid native question event');
      return Promise.resolve();
    }
    if (type === 'question_asked') {
      if (!Array.isArray(request.questions) || request.questions.length === 0) {
        console.error('Walker received native question.asked without questions');
        return Promise.resolve();
      }
      const data = { requestID, sessionID, questions: request.questions };
      if (request.tool || properties.tool) data.tool = request.tool || properties.tool;
      return report(sessionID, '', [{ type, data }], null, null, null).catch(() => {});
    }
    if (type === 'question_replied') {
      if (!Array.isArray(request.answers)) {
        console.error('Walker received native question.replied without answers');
        return Promise.resolve();
      }
      return report(sessionID, '', [{ type, data: { requestID, sessionID, answers: request.answers } }], null, null, null).catch(() => {});
    }
    return report(sessionID, '', [{ type, data: { requestID, sessionID } }], null, null, null).catch(() => {});
  }

  onPluginEvent('question.asked', async (event) => {
    await reportQuestionEvent('question_asked', event);
  });

  onPluginEvent('question.replied', async (event) => {
    await reportQuestionEvent('question_replied', event);
  });

  onPluginEvent('question.rejected', async (event) => {
    await reportQuestionEvent('question_rejected', event);
  });

  function reportFormEvent(kind, event) {
    const properties = eventProperties(event);
    const form = properties.form || properties;
    if (kind === 'form.created') {
      rememberForm(form);
      return reportQuestionEvent('question_asked', { properties: {
        sessionID: form.sessionID,
        id: form.id,
        questions: questionsFromForm(form),
        tool: form.metadata && form.metadata.tool,
      } });
    }
    if (kind === 'form.replied') {
      return reportQuestionEvent('question_replied', { properties: {
        sessionID: properties.sessionID,
        id: properties.id,
        answers: answersFromForm(properties.id, properties.answer || {}),
      } });
    }
    return reportQuestionEvent('question_rejected', { properties: {
      sessionID: properties.sessionID || form.sessionID,
      id: properties.id || form.id,
    } });
  }

  onPluginEvent('form.created', async (event) => {
    await reportFormEvent('form.created', event);
  });

  onPluginEvent('form.replied', async (event) => {
    await reportFormEvent('form.replied', event);
  });

  onPluginEvent('form.cancelled', async (event) => {
    await reportFormEvent('form.cancelled', event);
  });

  onPluginEvent('todo.updated', async (event) => {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    await report(sessionId, '', [{ type: 'todo', data: { todos: properties.todos || [] } }], null, null, null).catch(() => {});
  });

  async function reportCompacted(event) {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    await report(sessionId, '', [{ type: 'compacted', data: { sessionID: sessionId } }], null, null, null).catch(() => {});
  }
  onPluginEvent('session.compacted', reportCompacted);
  onPluginEvent('session.compaction.ended', reportCompacted);

  onPluginEvent('file.edited', async (event) => {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    await report(sessionId, '', [{ type: 'file_edited', data: {
      path: properties.path || '',
      action: properties.action || 'edit',
      linesAdded: properties.linesAdded,
      linesRemoved: properties.linesRemoved,
    } }], null, null, null).catch(() => {});
  });

  async function reportCommand(event) {
    const properties = eventProperties(event);
    const shell = properties.shell || {};
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    const exitCode = properties.exitCode !== undefined ? properties.exitCode : (shell.exit !== undefined ? shell.exit : -1);
    await report(sessionId, '', [{ type: 'command_executed', data: {
      command: properties.command || shell.command || '',
      exitCode: exitCode,
    } }], null, null, null).catch(() => {});
  }
  onPluginEvent('command.executed', reportCommand);
  onPluginEvent('session.shell.ended', reportCommand);

  onPluginEvent('message.part.updated', async (event) => {
    const properties = eventProperties(event);
    const sessionId = properties.sessionID || properties.sessionId || activeSessionId;
    if (!sessionId) return;
    if (activeDeliveries.has(sessionId)) return;
    const part = properties.part || {};
    if (part.type === 'file' || part.type === 'patch') {
      await report(sessionId, '', [{ type: 'file_edited', data: {
        path: part.path || part.file || part.name || '',
        action: part.type === 'patch' ? 'patch' : (part.action || 'edit'),
        linesAdded: part.linesAdded,
        linesRemoved: part.linesRemoved,
      } }], null, null, null).catch(() => {});
    }
  });

  const timer = setInterval(tick, POLL_INTERVAL_MS);
  if (timer.unref) timer.unref();
  tick();

  const dispose = async () => {
    if (stopped) return;
    stopped = true;
    clearInterval(timer);
    for (const stop of eventStops) {
      try { stop(); } catch (_) {}
    }
    eventStops.length = 0;
    for (const [sid, entry] of activeDeliveries) {
      if (entry.heartbeatTimer) clearInterval(entry.heartbeatTimer);
    }
    activeDeliveries.clear();
    clearQuestionDelivery();
    await post(DISPOSE_URL, { runtimeId }).catch(() => {});
  };
  if (api.lifecycle && typeof api.lifecycle.onDispose === 'function') api.lifecycle.onDispose(dispose);
  if (api.lifecycle && api.lifecycle.signal) api.lifecycle.signal.addEventListener('abort', dispose, { once: true });
  return dispose;
}

export { setup };

export default {
  id: 'walker-tui-bridge',
  setup,
  tui: setup,
};
`;
}

function getV2PluginEntrySource(bridgeSpecifier) {
  const specifier = typeof bridgeSpecifier === 'string' && bridgeSpecifier
    ? bridgeSpecifier
    : './walker-tui-bridge.js';
  if (!/^\.{1,2}\/walker-tui-bridge\.js$/.test(specifier)) {
    throw new Error('invalid V2 bridge specifier');
  }
  return `import { Plugin } from '@opencode/plugin/tui';
import { setup } from '${specifier}';

export default Plugin.define({
  id: 'walker-tui-bridge',
  setup,
});
`;
}

function getV2PackageManifest() {
  return JSON.stringify({
    name: 'walker-tui-bridge',
    type: 'module',
    exports: { './tui': './tui.js' },
  }, null, 2) + '\n';
}

function getV1PluginEntrySource() {
  return `import { setup } from './walker-tui-bridge.js';

export default {
  id: 'walker-tui-bridge',
  setup,
  tui(api) {
    return setup(api);
  },
};
`;
}

module.exports = { getPluginSource, getV2PluginEntrySource, getV1PluginEntrySource, getV2PackageManifest };
